-- ============================================================================
-- RF Performance — Avaliações e Certificações
-- Catálogo Ampliado — Método VAP — Teste 7
-- Fase 2B — cadastro em RASCUNHO para homologação controlada
--
-- Teste 7:
--   Liderança e Perfis Comportamentais DISC
--   15 questões de Liderança + 15 questões de DISC
--
-- Fonte primária já cadastrada na Fase 2A:
--   O Método VAP — Vendedor de Alta Performance
--   1ª edição em português · Rio de Janeiro, 2024
--   ISBN 978-65-01-07964-6
--   SHA-256: d28448b0b2e377af5233b939543bafb165d75d865547ef1627335f5a8b912b84
--
-- Documento de autoria das questões:
--   Sistema de Certificação Comercial — Método VAP
--   Testes 6 a 10 · versão para homologação interna · Agosto de 2026
--   SHA-256: 8b8744e0779fce01a2f505d22a700e4e88878c7848a9845968e2b2e66a263820
--
-- SEGURANÇA / ESCOPO
--   - Não altera Testes 1 a 6.
--   - Não recria a fonte Método VAP.
--   - Não cria grant de acesso.
--   - Não publica o Teste 7.
--   - Não cria tentativa.
--   - Gabarito permanece em private.assessment_question_keys.
--   - O corte 100/100 nesta versão é propositalmente fail-closed enquanto
--     a política de aprovação do novo catálogo não for definida.
-- ============================================================================

begin;

do $guard$
declare
  v_org_id uuid := '414a2e84-bc62-4c64-99ee-76db1cbc4654'::uuid;
begin
  if not exists (
    select 1
    from public.organizations o
    where o.id = v_org_id
      and o.slug = 'rf-consorcios'
      and o.status = 'active'
      and o.archived_at is null
  ) then
    raise exception 'VAP Teste 7 abortado: organização RF esperada não localizada/ativa.';
  end if;

  if (
    select count(*)
    from public.assessment_tests t
    where t.organization_id = v_org_id
      and t.archived_at is null
      and t.sequence_no between 1 and 6
  ) <> 6 then
    raise exception 'VAP Teste 7 abortado: catálogo-base Testes 1 a 6 não está íntegro.';
  end if;

  if not exists (
    select 1
    from public.assessment_tests t
    join public.assessment_test_versions tv
      on tv.test_id = t.id
     and tv.organization_id = t.organization_id
     and tv.archived_at is null
    where t.organization_id = v_org_id
      and t.sequence_no = 6
      and t.code = 'teste_6_vap_fundamentos_mentalidade_valor'
      and t.status = 'draft'
      and tv.version_code = '2026.08-v1'
      and tv.status = 'draft'
      and t.archived_at is null
  ) then
    raise exception 'VAP Teste 7 abortado: Teste 6 VAP esperado não está presente em draft.';
  end if;

  if not exists (
    select 1
    from public.source_material_versions smv
    join public.source_materials sm
      on sm.id = smv.source_material_id
     and sm.organization_id = smv.organization_id
    where sm.id = '2831b27b-035b-54fd-a3cc-d8a23a509a82'::uuid
      and smv.id = 'a20ad8ff-b3f8-5106-b96e-346fa342d098'::uuid
      and sm.organization_id = v_org_id
      and sm.code = 'metodo_vap_vendedor_alta_performance'
      and sm.material_type = 'book'
      and sm.status = 'active'
      and smv.version_code = '1a-edicao-2024'
      and smv.status = 'active'
      and lower(smv.content_sha256) = 'd28448b0b2e377af5233b939543bafb165d75d865547ef1627335f5a8b912b84'
      and sm.archived_at is null
      and smv.archived_at is null
  ) then
    raise exception 'VAP Teste 7 abortado: fonte Método VAP/versionamento esperado não confere.';
  end if;

  if exists (
    select 1
    from public.assessment_tests t
    where t.organization_id = v_org_id
      and t.archived_at is null
      and (
        t.sequence_no = 7
        or t.code = 'teste_7_vap_lideranca_disc'
        or t.id = '41106d9b-7db0-5ea3-9693-f625c58f5936'::uuid
      )
  ) then
    raise exception 'VAP Teste 7 abortado: já existe teste ocupando a identidade/seq. 7.';
  end if;

  if exists (
    select 1
    from public.competency_domains c
    where c.organization_id = v_org_id
      and c.archived_at is null
      and (
        c.sequence_no between 35 and 36
        or c.code in ('vap_lideranca','vap_disc')
        or c.id in (
          '303369bb-a347-5987-b89f-2aba9f19aab0'::uuid,
          'ef6219de-097c-567e-a0ae-ce93a50022ab'::uuid
        )
      )
  ) then
    raise exception 'VAP Teste 7 abortado: identidade/sequência das competências VAP já está ocupada.';
  end if;
end
$guard$;

